# Surah Al-i-Imran (chapter 3) — part 18: ayat 172-183 (IDs 465-476)
SURAH = 3

ENTRIES = {
465: (
"وہ لوگ جنہوں نے اللہ اور اس کے رسول کی پکار پر لبیک کہا — بعد اس کے کہ انہیں چوٹ لگی تھی — جو ان میں سے نیکی کریں اور (اللہ سے) ڈریں — ان کے لیے بہت بڑا اجر ہے۔",
"""۱۔ اُحد کے بعد حمراء الاسد کے لیے فوری لبیک — مسلمانوں کی وفاداری کی مثال۔
۲۔ ’’الَّذِينَ اسْتَجَابُوا لِلّٰہِ وَالرَّسُولِ مِن بَعْدِ مَا أَصَابَهُمُ الْقَرْحُ‘‘ — وہ لوگ جنہوں نے اللہ اور اس کے رسول کی پکار پر لبیک کہا — بعد اس کے کہ انہیں چوٹ لگی تھی — یعنی اُحد میں زخمی ہونے کے باوجود نبی ﷺ کی دعوت پر فوراً نکل کھڑے ہوئے۔
۳۔ ’’لِّلَّذِينَ أَحْسَنُوا مِنْهُمْ وَاتَّقَوْا أَجْرٌ عَظِيمٌ‘‘ — جو ان میں سے نیکی کریں اور (اللہ سے) ڈریں — ان کے لیے بہت بڑا اجر ہے۔
۴۔ عملی سبق: زخمی یا تھکے ہونے کے باوجود دین کے کام میں لبیک کہو؛ اللہ ضرور بدلہ دے گا۔"""
),
466: (
"وہ لوگ جن سے لوگوں نے کہا: بے شک لوگوں نے تمہارے خلاف جمع ہوئے ہیں — پس ان سے ڈرو — تو اس (بات) نے ان کا ایمان بڑھا دیا — اور انہوں نے کہا: ہمیں اللہ کافی ہے — اور وہ سب سے اچھا کارساز ہے۔",
"""۱۔ خوف کی خبر کے باوجود ایمان میں اضافہ — مسلمانوں کا فرسانہ۔
۲۔ ’’الَّذِينَ قَالَ لَهُمُ النَّاسُ إِنَّ النَّاسَ قَدْ جَمَعُوا لَكُمْ فَاخْشَوْهُمْ فَزَادَهُمْ إِيمَانًا‘‘ — وہ لوگ جن سے لوگوں نے کہا: بے شک لوگوں نے تمہارے خلاف جمع ہوئے ہیں — پس ان سے ڈرو — تو اس (بات) نے ان کا ایمان بڑھا دیا — یعنی خوف کی خبر سن کر ایمان مزید بڑھ گیا۔
۳۔ ’’وَقَالُوا حَسْبُنَا اللّٰہُ وَنِعْمَ الْوَكِيلُ‘‘ — اور انہوں نے کہا: ہمیں اللہ کافی ہے — اور وہ سب سے اچھا کارساز ہے — یعنی یہ کلمہ اُسی وقت سے مشہور ہے۔
۴۔ عملی سبق: مشکل وقت میں ’’حَسْبُنَا اللّٰہُ وَنِعْمَ الْوَكِيلُ‘‘ پڑھا کرو — اللہ ہی کافی ہے۔"""
),
467: (
"پس وہ اللہ کی نعمت اور فضل کے ساتھ لوٹے — کوئی برائی انہیں نہ چھونے پائی — اور انہوں نے اللہ کی رضا کی پیروی کی — اور اللہ بہت بڑے فضل والا ہے۔",
"""۱۔ بھروسے کا انعام — محفوظ واپسی اور اللہ کی رضا۔
۲۔ ’’فَانقَلَبُوا بِنِعْمَۃٍ مِّنَ اللّٰہِ وَفَضْلٍ لَّمْ يَمْسَسْهُمْ سُوءٌ‘‘ — پس وہ اللہ کی نعمت اور فضل کے ساتھ لوٹے — کوئی برائی انہیں نہ چھونے پائی — یعنی خدا نے انہیں سلامت واپس کیا۔
۳۔ ’’وَاتَّبَعُوا رِضْوَانَ اللّٰہِ وَاللّٰہُ ذُو فَضْلٍ عَظِيمٍ‘‘ — اور انہوں نے اللہ کی رضا کی پیروی کی — اور اللہ بہت بڑے فضل والا ہے۔
۴۔ عملی سبق: اللہ کے حکم پر بھروسہ رکھو؛ وہ تمہاری حفاظت کرے گا۔"""
),
468: (
"یہ شیطان ہے — وہ اپنے دوستوں کو ڈراتا ہے — پس تم ان سے نہ ڈرو — اور مجھ سے ڈرو اگر تم ایمان والے ہو۔",
"""۱۔ دشمن کا خوف — شیطان کا ہتھیار۔
۲۔ ’’إِنَّمَا ذَٰلِكُمُ الشَّيْطَانُ يُخَوِّفُ أَوْلِيَاءَهُ فَلَا تَخَافُوهُمْ وَخَافُونِ‘‘ — یہ شیطان ہے — وہ اپنے دوستوں کو ڈراتا ہے — پس تم ان سے نہ ڈرو — اور مجھ سے ڈرو — یعنی دشمن کا خوف شیطان کا وسوسہ ہے — اصل خوف صرف اللہ کا ہونا چاہیے۔
۳۔ ’’إِن كُنتُم مُّؤْمِنِينَ‘‘ — اگر تم ایمان والے ہو۔
۴۔ عملی سبق: دشمن سے نہیں، صرف اللہ سے ڈرو — ایمان اسی کا نام ہے۔"""
),
469: (
"اور آپ کو ان لوگوں کی طرف سے غمگین نہ ہوؤ جو کفر میں جلدی کرتے ہیں — بے شک وہ اللہ کو کچھ نقصان نہیں پہنچا سکتے — اللہ چاہتا ہے کہ انہیں آخرت میں کوئی حصہ نہ دے — اور ان کے لیے بہت بڑا عذاب ہے۔",
"""۱۔ کفار کی رفتار کا غم نہ کرو — ان کا کوئی نقصان اللہ کو نہیں پہنچا سکتا۔
۲۔ ’’وَلَا يَحْزُنْكَ الَّذِينَ يُسَارِعُونَ فِي الْكُفْرِ‘‘ — اور آپ کو ان لوگوں کی طرف سے غمگین نہ ہوؤ جو کفر میں جلدی کرتے ہیں — یعنی ان کی بغاوت سے مایوس نہ ہوں۔
۳۔ ’’إِنَّهُمْ لَن يَضُرُّوا اللّٰہَ شَيْئًا‘‘ — بے شک وہ اللہ کو کچھ نقصان نہیں پہنچا سکتے۔
۴۔ ’’يُرِيدُ اللّٰہُ أَلَّا يَجْعَلَ لَهُمْ حَظًّا فِي الْآخِرَۃِ وَلَهُمْ عَذَابٌ عَظِيمٌ‘‘ — اللہ چاہتا ہے کہ انہیں آخرت میں کوئی حصہ نہ دے — اور ان کے لیے بہت بڑا عذاب ہے۔
۵۔ عملی سبق: بدمعاشوں کی رفتار کا غم نہ کرو؛ اللہ کا فیصلہ آخری ہے۔"""
),
470: (
"بے شک جنہوں نے ایمان کے بدلے کفر خریدا — وہ اللہ کو کچھ نقصان نہیں پہنچا سکتے — اور ان کے لیے دردناک عذاب ہے۔",
"""۱۔ ایمان بیچ کر کفر خریدنا — سب سے بڑی تجارتی ناکامی۔
۲۔ ’’إِنَّ الَّذِينَ اشْتَرَوُا الْكُفْرَ بِالْإِيمَانِ لَن يَضُرُّوا اللّٰہَ شَيْئًا‘‘ — بے شک جنہوں نے ایمان کے بدلے کفر خریدا — وہ اللہ کو کچھ نقصان نہیں پہنچا سکتے — یعنی ان کا نقصان خود کا ہے۔
۳۔ ’’وَلَهُمْ عَذَابٌ أَلِيمٌ‘‘ — اور ان کے لیے دردناک عذاب ہے۔
۴۔ عملی سبق: ایمان کو دنیا کی کسی بھی چیز سے بیچنے کا خیال بھی مت لاؤ۔"""
),
471: (
"اور ہرگز وہ لوگ جنہوں نے کفر کیا یہ خیال نہ کریں کہ جو ہم انہیں مہلت دیتے ہیں — وہ ان کے لیے بہتر ہے — ہم انہیں صرف اس لیے مہلت دیتے ہیں کہ وہ گناہ میں زیادہ بڑھ جائیں — اور ان کے لیے رسوا کن عذاب ہے۔",
"""۱۔ کفار کو مہلت دینا — سزا کو مؤخر کرنا ہے، معافی نہیں۔
۲۔ ’’وَلَا يَحْسَبَنَّ الَّذِينَ كَفَرُوا أَنَّمَا نُمْلِي لَهُمْ خَيْرٌ لِّأَنفُسِهِمْ‘‘ — اور ہرگز وہ لوگ جنہوں نے کفر کیا یہ خیال نہ کریں کہ جو ہم انہیں مہلت دیتے ہیں — وہ ان کے لیے بہتر ہے۔
۳۔ ’’إِنَّمَا نُمْلِي لَهُمْ لِيَزْدَادُوا إِثْمًا‘‘ — ہم انہیں صرف اس لیے مہلت دیتے ہیں کہ وہ گناہ میں زیادہ بڑھ جائیں — یعنی مہلت ان کے گناہ میں اضافہ کا ذریعہ ہے۔
۴۔ ’’وَلَهُمْ عَذَابٌ مُّهِينٌ‘‘ — اور ان کے لیے رسوا کن عذاب ہے۔
۵۔ عملی سبق: زندگی کی مہلت کو توبہ کا سنہری موقع سمجھو؛ غفلت میں نہ رہو۔"""
),
472: (
"اللہ ایسا نہیں تھا کہ مومنین کو اس حالت پر چھوڑ دے جس پر تم ہو — جب تک کہ وہ کھوٹے کو کھرے سے جدا کر نہ دے — اور اللہ ایسا نہیں کہ تمہیں غیب پر مطلع کرے — لیکن اللہ اپنے رسولوں میں سے جسے چاہے چُنتا ہے — پس اللہ پر اور اس کے رسولوں پر ایمان لاؤ — اور اگر تم ایمان لاؤ اور (اللہ سے) ڈرو تو تمہارے لیے بہت بڑا اجر ہے۔",
"""۱۔ قیامت سے پہلے تطہیر — ایمان والے کھوٹے سے الگ ہوں گے۔
۲۔ ’’مَا كَانَ اللّٰہُ لِيَذَرَ الْمُؤْمِنِينَ عَلَىٰ مَا أَنتُمْ عَلَيْهِ حَتَّىٰ يَمِيزَ الْخَبِيثَ مِنَ الطَّيِّبِ‘‘ — اللہ ایسا نہیں تھا کہ مومنین کو اس حالت پر چھوڑ دے جس پر تم ہو — جب تک کہ وہ کھوٹے کو کھرے سے جدا کر نہ دے — یعنی اللہ نے آزمائشوں سے ایمان والوں کو صاف کرنا ضروری ہے۔
۳۔ ’’وَمَا كَانَ اللّٰہُ لِيُطْلِعَكُمْ عَلَى الْغَيْبِ‘‘ — اور اللہ ایسا نہیں کہ تمہیں غیب پر مطلع کرے — یعنی مکمل غیب جاننا اللہ کے سوا کسی کا حصہ نہیں۔
۴۔ ’’وَلَٰكِنَّ اللّٰہَ يَجْتَبِي مِن رُّسُلِهِ مَن يَشَاءُ‘‘ — لیکن اللہ اپنے رسولوں میں سے جسے چاہے چُنتا ہے — یعنی وحی کے ذریعے غیب کا علم اللہ اپنے چنے ہوئے رسولوں کو دیتا ہے۔
۵۔ ’’فَآمِنُوا بِاللّٰہِ وَرُسُلِهِ وَإِن تُؤْمِنُوا وَتَتَّقُوا فَلَكُمْ أَجْرٌ عَظِيمٌ‘‘ — پس اللہ پر اور اس کے رسولوں پر ایمان لاؤ — اور اگر تم ایمان لاؤ اور (اللہ سے) ڈرو تو تمہارے لیے بہت بڑا اجر ہے۔
۶۔ عملی سبق: تکلیفوں میں صبر کرو؛ اللہ تمہیں ضرور کھرے کھوٹے سے الگ کرے گا۔"""
),
473: (
"اور ہرگز وہ لوگ — جو اس (مال) میں بخل کرتے ہیں جو اللہ نے انہیں اپنے فضل سے دیا — یہ خیال نہ کریں کہ وہ ان کے لیے بہتر ہے — بلکہ وہ ان کے لیے برا ہے — عنقریب وہ قیامت کے دن اس (بخل) میں طوق پہنائیں جائیں گے — اور اللہ ہی آسمانوں اور زمین کی وراثت (کا مالک) ہے — اور اللہ تمہارے عمل سے باخبر ہے۔",
"""۱۔ بخل — دنیا میں بھی برا اور آخرت میں بھی۔
۲۔ ’’وَلَا يَحْسَبَنَّ الَّذِينَ يَبْخَلُونَ بِمَا آتَاهُمُ اللّٰہُ مِن فَضْلِهِ هُوَ خَيْرًا لَّهُمْ‘‘ — اور ہرگز وہ لوگ — جو اس (مال) میں بخل کرتے ہیں جو اللہ نے انہیں اپنے فضل سے دیا — یہ خیال نہ کریں کہ وہ ان کے لیے بہتر ہے۔
۳۔ ’’بَلْ هُوَ شَرٌّ لَّهُمْ‘‘ — بلکہ وہ ان کے لیے برا ہے — یعنی بخل سے دنیا اور آخرت دونوں کا نقصان۔
۴۔ ’’سَيُطَوَّقُونَ مَا بَخِلُوا بِهِ يَوْمَ الْقِيَامَۃِ‘‘ — عنقریب وہ قیامت کے دن اس (بخل) میں طوق پہنائیں جائیں گے — یعنی بخل کیا ہوا مال طوق بن کر گردن میں پڑے گا۔
۵۔ ’’وَلِلّٰہِ مِيرَاثُ السَّمَاوَاتِ وَالْأَرْضِ وَاللّٰہُ بِمَا تَعْمَلُونَ خَبِيرٌ‘‘ — اور اللہ ہی آسمانوں اور زمین کی وراثت (کا مالک) ہے — اور اللہ تمہارے عمل سے باخبر ہے۔
۶۔ عملی سبق: اللہ کے دیے ہوئے مال میں بخل نہ کرو؛ خیرات کرو — یہ تمہارا اصل سرمایہ ہے۔"""
),
474: (
"بے شک اللہ نے اس قوم کی بات سن لی جنہوں نے کہا: بے شک اللہ فقیر ہے اور ہم غنی (امیر) ہیں — ہم ضرور وہ لکھیں گے جو انہوں نے کہا اور انبیا کا بلا حق قتل کرنا — اور ہم کہیں گے: چکھو آگ کا عذاب۔",
"""۱۔ ایک سنگین توہین — اللہ کو فقیر کہنا۔
۲۔ ’’لَّقَدْ سَمِعَ اللّٰہُ قَوْلَ الَّذِينَ قَالُوا إِنَّ اللّٰہَ فَقِيرٌ وَنَحْنُ أَغْنِيَاءُ‘‘ — بے شک اللہ نے اس قوم کی بات سن لی جنہوں نے کہا: بے شک اللہ فقیر ہے اور ہم غنی (امیر) ہیں — یعنی بعض اہلِ کتاب نے اللہ کو حاجت مند کہا تھا۔
۳۔ ’’سَنَكْتُبُ مَا قَالُوا وَقَتْلَهُمُ الْأَنبِيَاءَ بِغَيْرِ حَقٍّ‘‘ — ہم ضرور وہ لکھیں گے جو انہوں نے کہا اور انبیا کا بلا حق قتل کرنا — یعنی اللہ ان کے گناہوں کا ریکارڈ رکھ رہا ہے۔
۴۔ ’’وَنَقُولُ ذُوقُوا عَذَابَ الْحَرِيقِ‘‘ — اور ہم کہیں گے: چکھو آگ کا عذاب۔
۵۔ عملی سبق: اللہ کے بارے میں بے ادبی کبھی نہ کرو؛ ہر بات اللہ کے ریکارڈ میں محفوظ ہے۔"""
),
475: (
"یہ اس (گناہ) کی وجہ سے ہے جو تمہارے ہاتھوں نے آگے بھیجا — اور بے شک اللہ بندوں پر ظالم نہیں۔",
"""۱۔ عذاب کا سبب — خود اپنے اعمال۔
۲۔ ’’ذَٰلِكَ بِمَا قَدَّمَتْ أَيْدِيكُمْ‘‘ — یہ اس (گناہ) کی وجہ سے ہے جو تمہارے ہاتھوں نے آگے بھیجا — یعنی دنیا میں جو گناہ کیے وہی عذاب کا سبب ہیں۔
۳۔ ’’وَأَنَّ اللّٰہَ لَيْسَ بِظَلَّامٍ لِّلْعَبِيدِ‘‘ — اور بے شک اللہ بندوں پر ظالم نہیں — یعنی اللہ کا کوئی فیصلہ ظلم پر مبنی نہیں۔
۴۔ عملی سبق: ہر عمل کا حساب خود دینا ہے؛ اللہ کسی پر ظلم نہیں کرتا۔"""
),
476: (
"(یہ وہ لوگ ہیں) جنہوں نے کہا: بے شک اللہ نے ہم سے عہد لیا ہے کہ ہم کسی رسول پر ایمان نہ لائیں جب تک وہ ہمارے پاس ایسی قربانی نہ لائے جسے آگ کھا جائے — آپ کہیں: تم سے پہلے بھی رسول واضح دلائل اور وہ چیز (جس کا تم ذکر کرتے ہو) لے کر آئے — پس تم نے انہیں کیوں قتل کیا اگر تم سچے ہو؟",
"""۱۔ اہلِ کتاب کا ایک اور بہانہ — قربانی کی شرط۔
۲۔ ’’الَّذِينَ قَالُوا إِنَّ اللّٰہَ عَهِدَ إِلَيْنَا أَلَّا نُؤْمِنَ لِرَسُولٍ حَتَّىٰ يَأْتِيَنَا بِقُرْبَانٍ تَأْكُلُهُ النَّارُ‘‘ — (یہ وہ لوگ ہیں) جنہوں نے کہا: بے شک اللہ نے ہم سے عہد لیا ہے کہ ہم کسی رسول پر ایمان نہ لائیں جب تک وہ ہمارے پاس ایسی قربانی نہ لائے جسے آگ کھا جائے — یعنی ان کا دعویٰ تھا کہ آسمان سے آگ آ کر قربانی قبول کرنی چاہیے۔
۳۔ ’’قُلْ قَدْ جَاءَكُمْ رُسُلٌ مِّن قَبْلِي بِالْبَيِّنَاتِ وَبِالَّذِي قُلْتُمْ فَلِمَ قَتَلْتُمُوهُمْ إِن كُنتُمْ صَادِقِينَ‘‘ — آپ کہیں: تم سے پہلے بھی رسول واضح دلائل اور وہ چیز (جس کا تم ذکر کرتے ہو) لے کر آئے — پس تم نے انہیں کیوں قتل کیا اگر تم سچے ہو؟ — یعنی ان کے اس معیار کے رسول آئے تھے مگر انہوں نے انہیں قتل کر دیا — ان کا بہانہ غلط ثابت ہوا۔
۴۔ عملی سبق: بہانے بنانا ایمان کی راہ نہیں؛ سچی نیت سے حق قبول کرو۔"""
),
}
